-- 코드 순서와 다르게 나간다

@Test
@Transactional
void 순서() {
    Member m1 = new Member("m1", 10);
    em.persist(m1);
    System.out.println("1) 회원 저장");

    Team t = new Team("A팀");
    em.persist(t);
    System.out.println("2) 팀 저장");

    Member m2 = new Member("m2", 20, t);
    em.persist(m2);
    System.out.println("3) 회원 저장");

    System.out.println("--- flush ---");
    em.flush();
}

