-- 중간에 flush 하면 갈라진다

@Test
@Transactional
void 중간_flush() {
    Member old = memberRepository.findById(1L).orElseThrow();
    em.remove(old);
    em.flush();
    System.out.println("--- 첫 flush 끝 ---");

    em.persist(new Member("새회원", 40));
    em.flush();
}

