-- 저장하고 다른 컨텍스트에서 읽기

@Test
@Transactional
void 저장_조회() {
    Team t = new Team("A팀");
    em.persist(t);
    Member m = new Member("김", 20, t);
    memberRepository.save(m);

    em.flush();
    em.clear();
    System.out.println("--- 새 컨텍스트 ---");

    Member found = memberRepository.findById(m.getId()).orElseThrow();
    System.out.println("이름: " + found.getUsername());
    System.out.println("--- 팀을 읽는다 ---");
    System.out.println("팀: " + found.getTeam().getName());
}

Hibernate: insert into team (name, team_id) values (?, ?)
Hibernate: insert into member (age, team_id, username, member_id)
           values (?, ?, ?, ?)
